from:
for (const [, blanks, rest] of clean.matchAll(OUTPUT_CREATED_LINE)) {
  if (rest !== "") {
    let end = rest.length;
    while (rest[end - 1] === " " || rest[end - 1] === "\t") {
      end--;
    }
    last = rest.slice(0, end);
  } else if (blanks !== "") {
    last = blanks[blanks.length - 1];
  }
}

